#ifndef APP_CPP_UPDATE_UPDATEMANIFEST_H
#define APP_CPP_UPDATE_UPDATEMANIFEST_H

#include <string>

namespace app::update {

// firmware-manifest.json as generated by CI (.gitea/workflows/build-firmware.yml)
// and served next to the firmware images. Paths are relative to the
// manifest's own URL. Integrity: the manifest is signed (verified by the
// platform adapter before parsing); the images are verified against the
// SHA-256 values in it.
struct UpdateManifest {
    std::string version;                // P4 app version, e.g. "0.1.0.57"
    std::string min_supported_version;  // installed version must be >= this
    std::string path;                   // P4 app image, relative
    std::string sha256;                 // hex, of the file at `path`

    bool has_coprocessor = false;
    std::string coprocessor_version;    // e.g. "2.12.3-sb.1"
    std::string coprocessor_path;       // c6fw container, relative
    std::string coprocessor_sha256;
};

// Parses and validates required fields; false with a short reason otherwise.
bool parse_update_manifest(const std::string& json, UpdateManifest& out, std::string& error);

// Compares dotted numeric versions ("0.1.0" < "0.1.0.1" < "0.2.0"); missing
// trailing components count as 0, a "-suffix" is ignored. Returns <0, 0, >0.
int compare_versions(const std::string& a, const std::string& b);

// Resolves `relative` against the directory of `manifest_url`
// ("https://host/a/firmware-manifest.json" + "firmware/x.bin" ->
// "https://host/a/firmware/x.bin"); absolute http(s) URLs pass through.
std::string resolve_url(const std::string& manifest_url, const std::string& relative);

} // namespace app::update

#endif // APP_CPP_UPDATE_UPDATEMANIFEST_H
